#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ask_long_secret KEY "Prompt" reads a hidden value that may arrive as several
# pasted lines (a long token wraps in the terminal). It ends at an empty line
# and drops every space and line break.
ask_long_secret() {
  local key="$1" prompt="$2" line value=""
  printf '  %s%s%s\n  ' "$BOLD" "$prompt" "$RESET"
  while IFS= read -rs line; do
    line="${line//$'\e[200~'/}"; line="${line//$'\e[201~'/}"
    [[ -z "${line//[[:space:]]/}" ]] && break
    value+="${line//[[:space:]]/}"
  done
  printf '\n'
  # A double paste repeats the token: keep the first copy.
  local rest="${value#sk-ant-}"
  if [[ "$rest" == *sk-ant-* ]]; then value="sk-ant-${rest%%sk-ant-*}"; fi
  printf -v "$key" '%s' "$value"
}

# The two logins only the owner can make, and a quick check of both:
#   login-wizard.sh            the Claude agents' own login (state/agent.env)
#   login-wizard.sh codex      the Checker's own Codex login (state/codex-home)
#   login-wizard.sh --status   one line for each: done, or what to run
# --status only checks that files exist and where the Codex login link points;
# it never opens a login file.

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"
_given_home="${HOME:-}"
HOME="$(/usr/bin/python3 -I -c "import os,pwd;print(os.path.realpath(pwd.getpwuid(os.getuid()).pw_dir))")"
unset ENGINE_CONFIG
. "$HERE/../lib/config.sh" || { echo "The engine config could not be read. Check engine/config.json" >&2; exit 1; }
HOME="$_given_home"; unset _given_home
STATE_DIR="$CFG_STATE"
CODEX_AUTH="$STATE_DIR/codex-home/auth.json"

# The Checker has its own Codex login when the login file is a plain file in
# the engine's state, not a link to the owner's own ~/.codex login.
codex_login_is_own() {
  [[ -e "$CODEX_AUTH" ]] || return 1
  case "$(/usr/bin/python3 -I -c 'import os,sys; print(os.path.realpath(sys.argv[1]))' "$CODEX_AUTH")" in
    "$STATE_DIR"/*) return 0 ;;
  esac
  return 1
}

login_status() {
  if [[ -f "$STATE_DIR/agent.env" ]]; then echo "Claude agents' login: done"
  else echo "Claude agents' login: to do: run engine/fence/login-wizard.sh"; fi
  if codex_login_is_own; then echo "Checker's own Codex login: done"
  else echo "Checker's own Codex login: to do: run engine/fence/login-wizard.sh codex"; fi
}

prove_stage() {
  stage "Prove the fence"
  say "The proof runs now: what each agent must not reach, what its fence"
  say "policy allows, and that each agent still works from inside the fence."
  pause "Press Enter to run it"
  local rc=0
  "$HERE/prove.sh" || rc=$?
  say ""
  if (( rc == 0 )); then say "Every check passed. Tell Claude: the fence proof passed."
  elif (( rc == 2 )); then say "The fence holds. The SKIP lines above say what is still to do."
  else warn "At least one check did not pass. Copy the lines above and send them to Claude."; fi
  pause "Press Enter to finish"
}

run_claude_login() {

TOTAL_STAGES=2
mkdir -p "$STATE_DIR"
ENV_FILE="$STATE_DIR/agent.env"

banner "Give the fenced agents their own Claude login"

# ── Stage 1: the agents' own token ────────────────────────────────────────
stage "Create the agents' login token"
say "The agents run inside a fence and cannot use your own Claude login."
say "This step makes a separate token for them, tied to your Claude plan."
step "A sign-in page opens in your browser. Approve it with your Claude account."
step "Back here, the terminal prints a long token that starts with sk-ant-."
step "Select the whole token and copy it. It is long and wraps onto a second line: take both lines."
pause "Press Enter to start the sign-in"
if ! "$CFG_REAL_CLAUDE" setup-token; then
  warn "claude setup-token did not finish. Sort that out, then run this wizard again."
  exit 1
fi
while :; do
  ask_long_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the whole token, press Enter, then press Enter again on the empty line. It stays hidden."
  if [[ "$CLAUDE_CODE_OAUTH_TOKEN" =~ ^sk-ant-[A-Za-z0-9_-]{80,}$ ]]; then break; fi
  warn "That was ${#CLAUDE_CODE_OAUTH_TOKEN} characters. A full token is about 100, so it was probably cut off at a line break."
  confirm "Paste it again?" || exit 1
done
write_env CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN"
note "Saved outside the project and outside the fence, readable only by you."
pause

# ── Stage 2: prove the fence ──────────────────────────────────────────────
prove_stage

finish
}

# Phase 1 ticket 14: the Checker signs in to Codex with a login of its own,
# kept in the engine's Codex home, instead of a link to the owner's ~/.codex.
run_codex_login() {

TOTAL_STAGES=3
CODEX_HOME_DIR="$STATE_DIR/codex-home"
SAVED_LINK="$CODEX_HOME_DIR/auth.json.owner-link"
CODEX_CLI="$CFG_ENGINE_DIR/node_modules/.bin/codex"

banner "Give the Checker its own Codex login"

# ── Stage 1: what changes ─────────────────────────────────────────────────
stage "What this does"
say "Today the Checker uses your own Codex login, through a link to your ~/.codex."
say "This step signs the Checker in separately. Its login is kept in the engine's"
say "own folder, and the link to your login is removed. Your own login is not touched."
if codex_login_is_own; then
  say ""
  say "The Checker already has a login of its own."
  if ! confirm "Sign it in again anyway?"; then prove_stage; finish; return 0; fi
fi
[[ -x "$CODEX_CLI" ]] || { warn "Codex is not installed in engine/node_modules. Run npm install in engine/ first."; exit 1; }
pause

# ── Stage 2: sign in ──────────────────────────────────────────────────────
stage "Sign the Checker in to Codex"
step "A sign-in page opens in your browser. Sign in with the ChatGPT account whose plan the Checker should use."
step "When the page says you are signed in, come back here."
pause "Press Enter to start the sign-in"
mkdir -p "$CODEX_HOME_DIR"
# Move the link aside first, so the sign-in can never write through it into your own login.
if [[ -L "$CODEX_AUTH" ]]; then mv "$CODEX_AUTH" "$SAVED_LINK"; fi
restore_link() {
  if [[ -L "$SAVED_LINK" && ! -e "$CODEX_AUTH" && ! -L "$CODEX_AUTH" ]]; then mv "$SAVED_LINK" "$CODEX_AUTH"; fi
}
trap 'restore_link; exit 1' INT TERM
if ! CODEX_HOME="$CODEX_HOME_DIR" PATH="$CFG_NODE24/bin:$PATH" "$CODEX_CLI" login; then
  restore_link; trap - INT TERM
  warn "The Codex sign-in did not finish. Nothing was changed; run this wizard again when ready."
  exit 1
fi
trap - INT TERM
if [[ -f "$CODEX_AUTH" && ! -L "$CODEX_AUTH" ]]; then
  chmod 600 "$CODEX_AUTH"
  rm -f "$SAVED_LINK"    # removes the link only; your own login file stays as it was
  say "The Checker now has its own Codex login. The link to yours is gone."
else
  restore_link
  warn "Codex did not save a login. Nothing was changed; run this wizard again."
  exit 1
fi
pause

# ── Stage 3: prove the fence ──────────────────────────────────────────────
prove_stage

finish
}

run_wizard() {
  case "${1:-}" in
    --status) login_status ;;
    "") run_claude_login ;;
    codex) run_codex_login ;;
    *) echo "Usage: engine/fence/login-wizard.sh [codex | --status]" >&2; exit 64 ;;
  esac
}

run_wizard "$@"; exit
